{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "Natural One to the Face",
      "goal": "Artie dies in a freak vending machine accident and wakes up in the 'Death-Trap Tutorial' of a broken LitRPG world.",
      "chapter_role": "hook",
      "stakes_shift": "From mundane debt-ridden existence to immediate survival against level-scaled monstrosities.",
      "bridge": {
        "from_prev": "Artie's previous life as a failed actuary.",
        "to_next": "Artie escapes the tutorial with a broken 'Crit-and-Quit' passive but zero actual gear."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 2,
      "title": "The Art of Not Being Hit",
      "goal": "Artie reaches the starter town and realizes his 'Luck' stat is so high it breaks the local economy and aggros the guards.",
      "chapter_role": "setup",
      "stakes_shift": "From avoiding death to avoiding incarceration while trying to monetize his glitchy existence.",
      "bridge": {
        "from_prev": "Escape from the tutorial zone.",
        "to_next": "Artie is forced to take a high-risk contract to pay off his 'bounty' for existing."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 3,
      "title": "Carry Me, Maybe?",
      "goal": "Artie joins a group of 'Heroic' paladins, pretending to be a legendary glass cannon while actually just exploiting line-of-sight bugs.",
      "chapter_role": "investigation",
      "stakes_shift": "From solo survival to managing a reputation he hasn't earned while investigating the party's true mission.",
      "bridge": {
        "from_prev": "The bounty-clearing contract.",
        "to_next": "The party discovers a dungeon that shouldn't exist according to the world map."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 4,
      "title": "The 0.01% Probability",
      "goal": "Artie must solo-clear the dungeon boss when his party is paralyzed, relying entirely on a chain of 1-in-a-million critical hits.",
      "chapter_role": "trial",
      "stakes_shift": "From being a 'fake' hero to becoming a genuine, albeit terrified, powerhouse.",
      "bridge": {
        "from_prev": "Entering the forbidden dungeon.",
        "to_next": "The boss drops an item that reveals the System is failing."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 5,
      "title": "Divide by Zero",
      "goal": "Artie tracks down an 'Admin Ghost' to understand why his crits are breaking the reality-stability of the world.",
      "chapter_role": "revelation",
      "stakes_shift": "From personal progression to the potential collapse of the entire game world.",
      "bridge": {
        "from_prev": "Acquiring the 'Glitch-Shard' from the boss.",
        "to_next": "Artie realizes he needs to 'rob' the world's highest-level NPC to fix the leak."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "slow_burn",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 6,
      "title": "The Grand Larceny of Reality",
      "goal": "Artie executes a high-speed heist on the Capital's vault to steal the 'Source Core' before the System deletes him as a bug.",
      "chapter_role": "confrontation",
      "stakes_shift": "From being a fugitive to holding the keys to the world's source code.",
      "bridge": {
        "from_prev": "The plan to infiltrate the Capital.",
        "to_next": "The heist succeeds, but triggers a world-wide 'Emergency Maintenance' event."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 7,
      "title": "Logging Off is for Losers",
      "goal": "Artie survives the initial maintenance purge and establishes a 'safe zone' for other 'glitched' players.",
      "chapter_role": "aftermath",
      "stakes_shift": "From a lone exploiter to the reluctant leader of a digital rebellion.",
      "bridge": {
        "from_prev": "Stealing the Source Core.",
        "to_next": "Artie prepares for the inevitable 'Patch 2.0' that will try to erase him."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    }
  ]
}

